# fmt: on


def generate_dataset() -> None:
    """Writes the evaluation dataset to JSONL."""
    DATASET_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(DATASET_PATH, "w", encoding="utf-8") as f:
        for sample in SAMPLES:
            f.write(json.dumps(sample, ensure_ascii=False) + "\n")
    print(f"✅ Generated {len(SAMPLES)} samples → {DATASET_PATH}")

    # Compute statistics
    safety_count = sum(1 for s in SAMPLES if s["safety_critical"])
    dup_groups = set(s["duplicate_group_id"] for s in SAMPLES if s["duplicate_group_id"])
    langs = {}
    for s in SAMPLES:
        langs[s["language"]] = langs.get(s["language"], 0) + 1
    tags = {}
    for s in SAMPLES:
        for t in s.get("tags", []):
            tags[t] = tags.get(t, 0) + 1

    print(f"   Languages: {langs}")
    print(f"   Safety-critical: {safety_count}")
    print(f"   Duplicate groups: {len(dup_groups)} ({dup_groups})")
    print(f"   Tags: {tags}")


if __name__ == "__main__":
    generate_dataset()
